from bisect import bisect_left, bisect_right

class Solution:
    def platesBetweenCandles(self, s: str, queries: List[List[int]]) -> List[int]:
        candles = [i for i, ch in enumerate(s) if ch == '|']
        pre = [0]
        for ch in s:
            pre.append(pre[-1] + (ch == '*'))
        res = []
        for l, r in queries:
            lo = bisect_left(candles, l)
            hi = bisect_right(candles, r) - 1
            if lo >= hi:
                res.append(0)
            else:
                res.append(pre[candles[hi] + 1] - pre[candles[lo]])
        return res

