class Solution {
    public int[] platesBetweenCandles(String s, int[][] queries) {
        int n = s.length();
        List<Integer> candles = new ArrayList<>();
        int[] pre = new int[n + 1];
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '|') candles.add(i);
            pre[i + 1] = pre[i] + (s.charAt(i) == '*' ? 1 : 0);
        }
        int[] res = new int[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int lo = firstAtLeast(candles, queries[qi][0]);
            int hi = firstAtLeast(candles, queries[qi][1] + 1) - 1;
            res[qi] = lo >= hi ? 0 : pre[candles.get(hi) + 1] - pre[candles.get(lo)];
        }
        return res;
    }

    private int firstAtLeast(List<Integer> a, int t) {
        int lo = 0, hi = a.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a.get(mid) < t) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

