    for (const [l, r] of queries) {
        const lo = lowerBound(l);
        const hi = lowerBound(r + 1) - 1;
        res.push(lo >= hi ? 0 : pre[candles[hi] + 1] - pre[candles[lo]]);
    }
    return res;
