class Solution:
    def platesBetweenCandles(self, s: str, queries: List[List[int]]) -> List[int]:
        n = len(s)
        pre = [0] * (n + 1)
        left = [-1] * n
        right = [-1] * n
        for i, ch in enumerate(s):
            pre[i + 1] = pre[i] + (ch == '*')
            left[i] = i if ch == '|' else (left[i - 1] if i else -1)
        for i in range(n - 1, -1, -1):
            if s[i] == '|':
                right[i] = i
            elif i + 1 < n:
                right[i] = right[i + 1]
        res = []
        for l, r in queries:
            a, b = right[l], left[r]
            res.append(pre[b + 1] - pre[a] if a < b else 0)
        return res

