class Solution {
public:
    vector<int> platesBetweenCandles(string s, vector<vector<int>>& queries) {
        int n = s.size();
        vector<int> pre(n + 1, 0), left(n, -1), right(n, -1);
        for (int i = 0; i < n; ++i) {
            pre[i + 1] = pre[i] + (s[i] == '*');
            left[i] = s[i] == '|' ? i : (i ? left[i - 1] : -1);
        }
        for (int i = n - 1; i >= 0; --i)
            right[i] = s[i] == '|' ? i : (i + 1 < n ? right[i + 1] : -1);
        vector<int> res;
        res.reserve(queries.size());
        for (auto& q : queries) {
            int a = right[q[0]], b = left[q[1]];
            res.push_back(a < b ? pre[b + 1] - pre[a] : 0);
        }
        return res;
    }
};

