class Solution {
    public int[] platesBetweenCandles(String s, int[][] queries) {
        int n = s.length();
        int[] pre = new int[n + 1];
        int[] left = new int[n], right = new int[n];
        Arrays.fill(left, -1);
        Arrays.fill(right, -1);
        for (int i = 0; i < n; i++) {
            pre[i + 1] = pre[i] + (s.charAt(i) == '*' ? 1 : 0);
            left[i] = s.charAt(i) == '|' ? i : (i > 0 ? left[i - 1] : -1);
        }
        for (int i = n - 1; i >= 0; i--)
            right[i] = s.charAt(i) == '|' ? i : (i + 1 < n ? right[i + 1] : -1);
        int[] res = new int[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int a = right[queries[qi][0]], b = left[queries[qi][1]];
            res[qi] = a < b ? pre[b + 1] - pre[a] : 0;
        }
        return res;
    }
};

